// Control-flow progression (Liang Ch. 3 + Ch. 4 style)
public class ControlFlow {
    public static void main(String[] args) {
        int score = 85;
        int attendancePercent = 92;
        char letter;

        // 1) Selection: conditions are checked top to bottom, so exactly one branch runs
        if (score >= 90) {
            letter = 'A';
        } else if (score >= 80) {
            letter = 'B';
        } else if (score >= 70) {
            letter = 'C';
        } else if (score >= 60) {
            letter = 'D';
        } else {
            letter = 'F';
        }
        System.out.println("Letter grade: " + letter);

        // 2) while loop: repeats while the condition holds
        int retries = 3;
        while (retries > 0) {
            System.out.println("Retry checks left: " + retries);
            retries--;
        }

        // 3) for loop: i <= 5 runs for i = 1..5
        int total = 0;
        for (int i = 1; i <= 5; i++) {
            total += i;
        }
        System.out.println("Sum 1..5 = " + total);

        // 4) switch: stacked case labels share one body; break stops fall-through
        switch (letter) {
            case 'A':
            case 'B':
                System.out.println("Strong performance.");
                break;
            case 'C':
            case 'D':
                System.out.println("Passing, but improve consistency.");
                break;
            default:
                System.out.println("Needs intervention plan.");
        }

        // 5) continue skips one iteration; break would leave the loop entirely
        for (int day = 1; day <= 7; day++) {
            if (day == 4) continue; // skip maintenance day
            if (attendancePercent < 80 && day > 5) break;
            System.out.println("Practice day " + day + " completed.");
        }
    }
}

