public class IfElseGradeLadder {
    static char grade(int score) {
        // Highest threshold first: the first true condition wins
        if (score >= 90) {
            return 'A';
        } else if (score >= 80) {
            return 'B';
        } else if (score >= 70) {
            return 'C';
        } else if (score >= 60) {
            return 'D';
        } else {
            return 'F';
        }
    }

    static char wrongOrderGrade(int score) {
        // Bug: every passing score matches the first test, so A/B/C are unreachable
        if (score >= 60) return 'D';
        else if (score >= 90) return 'A';
        else if (score >= 80) return 'B';
        else if (score >= 70) return 'C';
        else return 'F';
    }

    static int ticketPrice(int age, boolean member) {
        if (age < 12 || age >= 65) {
            return 5;
        } else if (member) {
            return 8;
        } else {
            return 12;
        }
    }

    static boolean hasData(int[] arr) {
        // && short-circuits: arr.length is never read when arr is null
        return arr != null && arr.length > 0;
    }

    public static void main(String[] args) {
        for (int score : new int[]{95, 90, 89, 70, 59}) {
            System.out.println("score " + score + " -> " + grade(score));
        }
        System.out.println("wrong order: 95 -> " + wrongOrderGrade(95) + " (score >= 60 was tested first)");

        System.out.println("ticket age 8: $" + ticketPrice(8, false));
        System.out.println("ticket age 30, member: $" + ticketPrice(30, true));
        System.out.println("ticket age 30, not member: $" + ticketPrice(30, false));

        System.out.println("hasData(null) = " + hasData(null));
        System.out.println("hasData({}) = " + hasData(new int[0]));
        System.out.println("hasData({7}) = " + hasData(new int[]{7}));
    }
}

