public class ForLoopTracing {
    public static void main(String[] args) {
        int n = 5;

        // Same body, different bound: < runs n times, <= runs n + 1 times
        int countLess = 0;
        for (int i = 0; i < n; i++) countLess++;
        int countLessEqual = 0;
        for (int i = 0; i <= n; i++) countLessEqual++;
        System.out.println("for (i = 0; i < 5; i++) ran " + countLess + " times");
        System.out.println("for (i = 0; i <= 5; i++) ran " + countLessEqual + " times");

        // Trace table: print the variables after each iteration
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += i * i;
            System.out.println("i=" + i + " i*i=" + (i * i) + " sum=" + sum);
        }

        // The update can be any expression
        StringBuilder steps = new StringBuilder();
        for (int i = 10; i > 0; i -= 3) {
            steps.append(i).append(' ');
        }
        System.out.println("i from 10 while i > 0, i -= 3: " + steps.toString().trim());

        // Enhanced for: visits each element, no index needed
        int[] data = {3, 1, 4, 1, 5};
        int max = data[0];
        for (int v : data) {
            if (v > max) max = v;
        }
        System.out.println("max of [3, 1, 4, 1, 5] = " + max);

        // Nested loops: the inner body runs rows * cols times -> O(n^2)
        int bodyRuns = 0;
        int pairs = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                bodyRuns++;
                if (i < j) pairs++;
            }
        }
        System.out.println("nested 4 x 4: inner body ran " + bodyRuns + " times, pairs with i < j: " + pairs);
    }
}

