public class WhileLoopsTrace {
    public static void main(String[] args) {
        // Unknown number of iterations: loop until the condition becomes false
        int n = 6;
        int steps = 0;
        StringBuilder path = new StringBuilder().append(n);
        while (n != 1) {
            n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
            steps++;
            path.append(" -> ").append(n);
        }
        System.out.println("collatz from 6: " + path + " (" + steps + " steps)");

        // Peel digits off the right; value shrinks every pass, so the loop ends
        int value = 2026;
        int digitSum = 0;
        int digits = 0;
        while (value > 0) {
            int d = value % 10;
            digitSum += d;
            digits++;
            value /= 10;
            System.out.println("digit=" + d + " sum=" + digitSum + " remaining=" + value);
        }
        System.out.println("2026 has " + digits + " digits, digit sum " + digitSum);

        // while tests first; do-while tests after the body, so it runs at least once
        int k = 10;
        int runs = 0;
        while (k < 5) {
            runs++;
            k++;
        }
        System.out.println("while (k < 5) starting at k = 10 ran " + runs + " times");

        k = 10;
        runs = 0;
        do {
            runs++;
            k++;
        } while (k < 5);
        System.out.println("do-while (k < 5) starting at k = 10 ran " + runs + " time");
    }
}

