public class SwitchFallThroughAndArrows {
    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }

    static int daysIn(int month) {
        switch (month) {
            case 2:
                return 28;              // return leaves the switch, so no break is needed
            case 4: case 6: case 9: case 11:
                return 30;              // stacked labels share one body
            default:
                return 31;
        }
    }

    static void unlockBadges(int level) {
        System.out.println("level " + level + " unlocks:");
        switch (level) {
            case 3:
                System.out.println("  gold badge");
                // no break: fall through on purpose
            case 2:
                System.out.println("  silver badge");
            case 1:
                System.out.println("  bronze badge");
                break;                  // stop here
            default:
                System.out.println("  no badges");
        }
    }

    static String kind(Day day) {
        // Arrow form never falls through; covering every constant means no default is needed
        return switch (day) {
            case SAT, SUN -> "weekend";
            case MON, TUE, WED, THU, FRI -> "weekday";
        };
    }

    public static void main(String[] args) {
        System.out.println("days in month 2, 4, 12: " + daysIn(2) + ", " + daysIn(4) + ", " + daysIn(12));
        unlockBadges(2);
        unlockBadges(0);
        for (Day day : new Day[]{Day.SAT, Day.WED}) {
            System.out.println(day + " -> " + kind(day));
        }
    }
}

