#include <iostream>
#include <string>

enum class Day { MON, TUE, WED, THU, FRI, SAT, SUN };
const char* DAY_NAMES[] = {"MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"};

int daysIn(int month) {
    switch (month) {
        case 2:
            return 28;
        case 4: case 6: case 9: case 11:
            return 30;
        default:
            return 31;
    }
}

void unlockBadges(int level) {
    std::cout << "level " << level << " unlocks:\n";
    switch (level) {
        case 3:
            std::cout << "  gold badge\n";
            [[fallthrough]];  // C++17 attribute: documents intentional fall-through
        case 2:
            std::cout << "  silver badge\n";
            [[fallthrough]];
        case 1:
            std::cout << "  bronze badge\n";
            break;
        default:
            std::cout << "  no badges\n";
    }
}

// C++ has no switch expression; a function that returns from each case is the usual stand-in
std::string kind(Day day) {
    switch (day) {
        case Day::SAT: case Day::SUN:
            return "weekend";
        case Day::MON: case Day::TUE: case Day::WED: case Day::THU: case Day::FRI:
            return "weekday";
    }
    return "";  // not reached; -Wall warns (-Wswitch) if an enum constant is missing above
}

int main() {
    std::cout << "days in month 2, 4, 12: " << daysIn(2) << ", " << daysIn(4) << ", " << daysIn(12) << "\n";
    unlockBadges(2);
    unlockBadges(0);
    for (Day day : {Day::SAT, Day::WED}) {
        std::cout << DAY_NAMES[static_cast<int>(day)] << " -> " << kind(day) << "\n";
    }
}

